package io.zingg.duckdb.compat;
import java.nio.file.Path; import java.util.List;
public record PipelineConfig(ZinggJob.Phase phase,List<Path> inputs,Path output,String predicate,io.zingg.duckdb.api.PathPolicy pathPolicy,Matcher.MatchConfig matcher,Path classifierModel,long maxModelBytes,long maxOutputBytes){public PipelineConfig{if(phase==null)throw new IllegalArgumentException("phase required");inputs=List.copyOf(inputs==null?List.of():inputs);if(inputs.isEmpty())throw new IllegalArgumentException("inputs required");if(output==null)throw new IllegalArgumentException("output required");predicate=predicate==null||predicate.isBlank()?"TRUE":predicate;if(maxModelBytes<0||maxOutputBytes<0)throw new IllegalArgumentException("artifact limits cannot be negative");} public PipelineConfig(ZinggJob.Phase phase,List<Path> inputs,Path output,String predicate){this(phase,inputs,output,predicate,null,null,null,256L*1024*1024,0);} public PipelineConfig(ZinggJob.Phase phase,List<Path> inputs,Path output,String predicate,io.zingg.duckdb.api.PathPolicy policy){this(phase,inputs,output,predicate,policy,null,null,256L*1024*1024,0);} public PipelineConfig(ZinggJob.Phase phase,List<Path> inputs,Path output,String predicate,io.zingg.duckdb.api.PathPolicy policy,Matcher.MatchConfig matcher){this(phase,inputs,output,predicate,policy,matcher,null,256L*1024*1024,0);} public PipelineConfig(ZinggJob.Phase phase,List<Path> inputs,Path output,String predicate,io.zingg.duckdb.api.PathPolicy policy,Matcher.MatchConfig matcher,Path classifierModel,long maxModelBytes){this(phase,inputs,output,predicate,policy,matcher,classifierModel,maxModelBytes,0);}}
